import{_ as t,o as a,c as o,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"Workspace Realtime Chat Channels, Threads, Mentions, Slash References, Scheduled Messages & 1:1 Voice Calls","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/04-task-chat-vault/workspace-chat-and-voice-calls/spec.md","filePath":"feature/modules/04-task-chat-vault/workspace-chat-and-voice-calls/spec.md"}'),s={name:"feature/modules/04-task-chat-vault/workspace-chat-and-voice-calls/spec.md"};function r(n,e,l,d,i,h){return a(),o("div",null,[...e[0]||(e[0]=[c('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="workspace-realtime-chat-channels-threads-mentions-slash-references-scheduled-messages-1-1-voice-calls" tabindex="-1">Workspace Realtime Chat Channels, Threads, Mentions, Slash References, Scheduled Messages &amp; 1:1 Voice Calls <a class="header-anchor" href="#workspace-realtime-chat-channels-threads-mentions-slash-references-scheduled-messages-1-1-voice-calls" aria-label="Permalink to &quot;Workspace Realtime Chat Channels, Threads, Mentions, Slash References, Scheduled Messages &amp; 1:1 Voice Calls&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>workspace-chat-and-voice-calls</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>04-task-chat-vault</code> — Task Workflow, Realtime Workspace Chat &amp; Encrypted S3 Vault</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>workspace-chat-collaboration</code>, <code>chat-attachments</code>, <code>chat-mention-inbox</code>, <code>chat-rich-composer</code>, <code>chat-scheduled-messages</code>, <code>chat-slash-reference</code>, <code>chat-thread-layout</code>, <code>chat-voice-calls</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/05-content-task-workflow/README.html">3.6 Content &amp; Workflow</a> (<code>3.6.28–3.6.31</code> Workspace Collaboration)</td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Provide a complete, Slack-caliber realtime Workspace communication hub (<code>pages/chat/index.tsx</code> &amp; Mobile <code>ChatScreen.tsx</code>) over STOMP/WebSocket + MongoDB (<code>chat_*</code> collections): public/private Workspace channels &amp; 1:1 DMs (<code>ChatChannelController</code>), resizable reply threads (<code>chat-thread-layout</code>), rich Markdown/Twemoji composer (<code>chat-rich-composer</code>), <code>@mention</code> inbox &amp; Do-Not-Disturb preferences (<code>chat-mention-inbox</code>), <code>/</code> slash references to Tasks/Campaigns/Materials (<code>chat-slash-reference</code>), direct S3 &amp; Repository attachments (<code>chat-attachments</code>), scheduled messages (<code>ChatScheduleController</code>), and <strong>Agora RTC 1:1 DM Voice Calls</strong> (<code>ChatCallController</code>).</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As an <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, or <code>Client</code> collaborating inside a Workspace, I want rich realtime channels, resizable message threads, <code>/</code> Task/Material cards, scheduled announcements, and 1-click 1:1 DM voice calls without leaving BrandHub for external chat apps.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Channels, DMs, Reactions, Pins &amp; Resizable Threads (<code>workspace-chat-collaboration</code>, <code>chat-thread-layout</code>):</strong> <code>ChatChannelController</code> and <code>ChatChannelMessageController</code> support Workspace channels, 1:1 DMs, emoji reactions (<code>PUT/DELETE .../reactions/{code}</code>), message pinning (<code>PUT/DELETE .../pin</code>), per-channel read cursors (<code>chat_channel_reads</code>), and a user-resizable right-hand thread panel (<code>ChatResizableThread.tsx</code>, <code>ChatThreadWidthMenu.tsx</code>).</li><li><strong>Rich Composer, <code>@Mentions</code> &amp; <code>/</code> Slash Entity Picker (<code>chat-rich-composer</code>, <code>chat-mention-inbox</code>, <code>chat-slash-reference</code>):</strong> <code>ChatRichComposer.tsx</code> supports bold/italic/code/lists, Twemoji picker, <code>@user</code> / <code>@channel</code> mentions (feeding <code>user_notifications</code> + mention filter inbox while respecting <code>ChatPreferenceController</code> DND/mute settings), and <code>ChatSlashMenu.tsx</code> (<code>/</code>) embedding live permission-checked Task, Campaign, and Material cards.</li><li><strong>Attachments &amp; Repository References (<code>chat-attachments</code>):</strong> <code>ChatAttachmentController</code> supports both direct file uploads (<code>POST .../attachments</code>) and zero-copy references to existing Workspace Repository materials (<code>POST .../attachments/repository</code>) with <code>ChatMediaLightbox.tsx</code> preview.</li><li><strong>Scheduled Messages (<code>chat-scheduled-messages</code>):</strong> <code>ChatScheduleController</code> (<code>POST/GET/PATCH/DELETE .../scheduled-messages</code>) lets users queue messages for future delivery in Workspace timezone, editable or cancellable prior to dispatch.</li><li><strong>1:1 DM Voice Calls (<code>chat-voice-calls</code>):</strong> <code>ChatCallController</code> (<code>/api/v1/workspaces/{workspaceId}/chat/calls</code>, <code>/{callId}/{accept|decline|cancel|end|connected|heartbeat}</code>, <code>/{callId}/token</code>) manages call state machine (<code>RINGING -&gt; CONNECTED -&gt; ENDED | MISSED | DECLINED</code>) in MongoDB <code>chat_calls</code>, mints short-lived server-signed RTC audio tokens, and renders <code>ChatCallBar.tsx</code> with mic mute &amp; heartbeat timeout cleanup.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>chat.{channels,composer,threads,mentions,slash,scheduled,calls,preferences}.*</code> in <code>src/i18n/locales/{vi,en}/chat.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/chat/index.tsx</code>, <code>pages/chat/components/{ChatWorkspace,ChatRichComposer,ChatResizableThread,ChatSlashMenu,ChatAttachmentComposer,ChatRepositoryPicker,ChatScheduledPanel,ChatCallBar}.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/chat/ChatScreen.tsx</code>, <code>src/components/chat/ChatChannelPicker.tsx</code>, <code>src/services/chatService.ts</code> (<code>@stomp/stompjs</code> 7.5)</li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET/POST/PATCH /api/v1/workspaces/{workspaceId}/chat/channels/**</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>)</td><td style="text-align:left;"><code>ChatChannelController</code> &amp; <code>ChatChannelMessageController</code> -&gt; channels, messages, threads, pins, reactions</td></tr><tr><td style="text-align:left;"><code>POST/GET /api/v1/workspaces/{workspaceId}/chat/channels/{channelId}/attachments[/repository]</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>)</td><td style="text-align:left;"><code>ChatAttachmentController</code> -&gt; file upload &amp; Material Repository link attachment</td></tr><tr><td style="text-align:left;"><code>POST/GET/PATCH/DELETE /api/v1/workspaces/{workspaceId}/chat/**/scheduled-messages/**</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>)</td><td style="text-align:left;"><code>ChatScheduleController</code> -&gt; scheduled message lifecycle</td></tr><tr><td style="text-align:left;"><code>GET/PUT /api/v1/workspaces/{workspaceId}/chat/preferences/**</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>)</td><td style="text-align:left;"><code>ChatPreferenceController</code> -&gt; DND &amp; channel mute preferences</td></tr><tr><td style="text-align:left;"><code>POST/GET /api/v1/workspaces/{workspaceId}/chat/calls/**</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>)</td><td style="text-align:left;"><code>ChatCallController</code> -&gt; 1:1 DM voice call signaling, heartbeat &amp; RTC token</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Voice Call Simultaneous Glare / Orphaned Ringing:</strong> Only 1 active call allowed per user (<code>409</code> on busy); missed-heartbeat reaper (<code>&gt; 30s</code> without <code>heartbeat</code>) auto-terminates dropped calls.</li><li><strong>Private Channel Boundary for <code>Client</code>:</strong> <code>Client</code> only sees channels where explicitly added as a channel member; <code>/</code> slash references verify Workspace/role visibility before rendering previews.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/05-content-task-workflow/README.html">3.6 Content &amp; Workflow</a> (<code>3.6.28–3.6.31</code> Workspace Collaboration)</li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/05-content-task-workflow.html">BA 05 Content &amp; Task Workflow</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const m=t(s,[["render",r]]);export{g as __pageData,m as default};
